#' Interval-Censoring Inputs (Python)
#'
#' 
#' @param data .
#' @param left .
#' @param right .
#' @param preview_rows .
#' @param showPreview .
#' @param showPlot .
#' @param showReport .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$counts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$distribution} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$leftOut} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$rightOut} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$kindOut} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyintervalcensoring <- function(
    data,
    left = NULL,
    right = NULL,
    preview_rows = 20,
    showPreview = TRUE,
    showPlot = FALSE,
    showReport = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyintervalcensoring requires jmvcore to be installed (restart may be required)")

    if ( ! missing(left)) left <- jmvcore::resolveQuo(jmvcore::enquo(left))
    if ( ! missing(right)) right <- jmvcore::resolveQuo(jmvcore::enquo(right))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(left), left, NULL),
            `if`( ! missing(right), right, NULL))


    options <- pyintervalcensoringOptions$new(
        left = left,
        right = right,
        preview_rows = preview_rows,
        showPreview = showPreview,
        showPlot = showPlot,
        showReport = showReport,
        showConsole = showConsole)

    analysis <- pyintervalcensoringClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

